// Copyright 2026 The Gitea Authors. All rights reserved.
// SPDX-License-Identifier: MIT

// Package ar implements a minimal, hardened reader and writer for the common ar
// archive format as used by Debian packages.
package ar

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"strconv"
	"time"
)

const (
	globalHeader = "!<arch>\n"
	headerSize   = 60
	headerEnd    = "`\n"
)

var (
	ErrInvalidHeader = errors.New("ar: invalid header")
	ErrWriteTooLong  = errors.New("ar: write too long")
)

// Header describes a single archive member.
type Header struct {
	Name    string
	ModTime time.Time
	Uid     int
	Gid     int
	Mode    int64
	Size    int64
}

// Reader provides sequential read access to an ar archive.
type Reader struct {
	r   io.Reader
	nb  int64
	pad int64
	// started tracks whether the global header was consumed
	started bool
}

func NewReader(r io.Reader) *Reader {
	return &Reader{r: r}
}

func parseField(b []byte) string {
	return string(bytes.TrimRight(b, " "))
}

func parseNumeric(b []byte, base int) (int64, error) {
	s := parseField(b)
	if s == "" {
		return 0, nil
	}
	return strconv.ParseInt(s, base, 64)
}

// Next advances to the next member and returns its header.
func (rd *Reader) Next() (*Header, error) {
	if !rd.started {
		buf := make([]byte, len(globalHeader))
		if _, err := io.ReadFull(rd.r, buf); err != nil {
			if err == io.ErrUnexpectedEOF {
				return nil, io.EOF
			}
			return nil, err
		}
		if string(buf) != globalHeader {
			return nil, ErrInvalidHeader
		}
		rd.started = true
	}

	if skip := rd.nb + rd.pad; skip > 0 {
		if _, err := io.CopyN(io.Discard, rd.r, skip); err != nil {
			return nil, err
		}
	}
	rd.nb, rd.pad = 0, 0

	buf := make([]byte, headerSize)
	if _, err := io.ReadFull(rd.r, buf); err != nil {
		if err == io.ErrUnexpectedEOF {
			return nil, fmt.Errorf("ar: truncated header: %w", err)
		}
		return nil, err
	}
	if string(buf[58:60]) != headerEnd {
		return nil, ErrInvalidHeader
	}

	hd := &Header{Name: parseField(buf[0:16])}

	mtime, err := parseNumeric(buf[16:28], 10)
	if err != nil {
		return nil, ErrInvalidHeader
	}
	hd.ModTime = time.Unix(mtime, 0)

	uid, err := parseNumeric(buf[28:34], 10)
	if err != nil {
		return nil, ErrInvalidHeader
	}
	hd.Uid = int(uid)

	gid, err := parseNumeric(buf[34:40], 10)
	if err != nil {
		return nil, ErrInvalidHeader
	}
	hd.Gid = int(gid)

	mode, err := parseNumeric(buf[40:48], 8)
	if err != nil {
		return nil, ErrInvalidHeader
	}
	hd.Mode = mode

	size, err := parseNumeric(buf[48:58], 10)
	if err != nil || size < 0 {
		return nil, ErrInvalidHeader
	}
	hd.Size = size

	rd.nb = size
	rd.pad = size % 2
	return hd, nil
}

// Read reads from the current member.
func (rd *Reader) Read(b []byte) (int, error) {
	if rd.nb == 0 {
		return 0, io.EOF
	}
	if int64(len(b)) > rd.nb {
		b = b[:rd.nb]
	}
	n, err := rd.r.Read(b)
	rd.nb -= int64(n)
	if err == io.EOF && rd.nb > 0 {
		err = io.ErrUnexpectedEOF
	}
	return n, err
}

// Writer provides sequential writing of an ar archive.
type Writer struct {
	w  io.Writer
	nb int64
}

func NewWriter(w io.Writer) *Writer { return &Writer{w: w} }

func (aw *Writer) WriteGlobalHeader() error {
	_, err := io.WriteString(aw.w, globalHeader)
	return err
}

func pad(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + string(bytes.Repeat([]byte{' '}, n-len(s)))
}

func (aw *Writer) WriteHeader(hdr *Header) error {
	aw.nb = hdr.Size
	h := pad(hdr.Name, 16) +
		pad(strconv.FormatInt(hdr.ModTime.Unix(), 10), 12) +
		pad(strconv.Itoa(hdr.Uid), 6) +
		pad(strconv.Itoa(hdr.Gid), 6) +
		pad("100"+strconv.FormatInt(hdr.Mode, 8), 8) +
		pad(strconv.FormatInt(hdr.Size, 10), 10) +
		headerEnd
	_, err := io.WriteString(aw.w, h)
	return err
}

func (aw *Writer) Write(b []byte) (int, error) {
	var err error
	if int64(len(b)) > aw.nb {
		b = b[:aw.nb]
		err = ErrWriteTooLong
	}
	n, werr := aw.w.Write(b)
	aw.nb -= int64(n)
	if werr != nil {
		return n, werr
	}
	if len(b)%2 == 1 {
		n2, _ := aw.w.Write([]byte{'\n'})
		return n + n2, err
	}
	return n, err
}
EOF
