// Copyright 2026 The Gitea Authors. All rights reserved.
// SPDX-License-Identifier: MIT

package ar

import (
	"bytes"
	"io"
	"strings"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func TestRoundTrip(t *testing.T) {
	var buf bytes.Buffer
	w := NewWriter(&buf)
	require.NoError(t, w.WriteGlobalHeader())
	for name, content := range map[string]string{"a": "odd", "b.txt": "even"} {
		require.NoError(t, w.WriteHeader(&Header{Name: name, Mode: 0o600, Size: int64(len(content))}))
		_, err := w.Write([]byte(content))
		require.NoError(t, err)
	}

	r := NewReader(&buf)
	got := map[string]string{}
	for {
		hd, err := r.Next()
		if err == io.EOF {
			break
		}
		require.NoError(t, err)
		b, err := io.ReadAll(r)
		require.NoError(t, err)
		got[hd.Name] = string(b)
	}
	assert.Equal(t, map[string]string{"a": "odd", "b.txt": "even"}, got)
}

func TestNegativeSize(t *testing.T) {
	hdr := "x" + strings.Repeat(" ", 15) + strings.Repeat(" ", 12+6+6) + "100644  " + "-5        " + "`\n"
	r := NewReader(strings.NewReader(globalHeader + hdr))
	_, err := r.Next()
	assert.ErrorIs(t, err, ErrInvalidHeader)
}
EOF
